 private void dossier(DebtorDossierRepository r,String... v){r.save(new DebtorDossier(v[0],v[1],v[2],v[3],v[4],v[5],v[6],v[7],v[8],v[9],v[10],v[11],v[12]));}
 private void cri(CriDocumentRepository documents,String code,String operation,String issuer,String sourceType,String availability,String finding,String source){documents.save(new CriDocument(code,operation,issuer,sourceType,availability,finding,source));}
 private void add(DebtorResearchRepository research,String debtor,String status,String assessment,String source){research.save(new DebtorResearch(debtor,status,assessment,source));}
